sp_widget.css:
/* =========================================================
   MEALCARE — PROFESSIONAL DARK FRAME NAVBAR
   ServiceNow Compatible
   HTML / IDs / Angular bindings unchanged
   Styling only
   ========================================================= */


/* =========================================================
   1. FULL WIDTH NAVBAR
   ========================================================= */

.cfa-navbar {
  position: relative;
  z-index: 9999;

  width: 100vw !important;
  max-width: 100vw !important;

  margin-left: calc(50% - 50vw) !important;
  margin-right: 0 !important;

  padding: 0 !important;

  min-height: 76px;

  background: #1E293B !important;

  border: none !important;
  border-bottom: 1px solid #334155 !important;

  box-shadow:
    0 6px 24px rgba(15, 23, 42, 0.18);

  font-family:
    "Segoe UI",
    Arial,
    sans-serif;

  box-sizing: border-box;

  overflow: hidden;
}


/* =========================================================
   2. BOX SIZING
   ========================================================= */

.cfa-navbar,
.cfa-navbar * {
  box-sizing: border-box;
}


/* =========================================================
   3. SUBTLE BACKGROUND GRID
   ========================================================= */

.cfa-navbar::before {
  content: "";

  position: absolute;
  inset: 0;

  pointer-events: none;

  background-image:
    linear-gradient(
      rgba(96, 165, 250, 0.025) 1px,
      transparent 1px
    ),
    linear-gradient(
      90deg,
      rgba(96, 165, 250, 0.025) 1px,
      transparent 1px
    );

  background-size: 34px 34px;

  opacity: 0.7;
}


/* =========================================================
   4. BOTTOM ACCENT LINE
   ========================================================= */

.cfa-navbar::after {
  content: "";

  position: absolute;

  left: 0;
  right: 0;
  bottom: 0;

  height: 2px;

  background:
    linear-gradient(
      90deg,
      transparent 0%,
      #2563EB 25%,
      #60A5FA 50%,
      #2563EB 75%,
      transparent 100%
    );

  opacity: 0.75;

  pointer-events: none;
}


/* =========================================================
   5. NAVBAR INNER
   ========================================================= */

.cfa-navbar-inner {
  position: relative;
  z-index: 2;

  width: 100% !important;
  max-width: 1400px !important;

  min-height: 76px;

  margin: 0 auto !important;

  padding: 0 6% !important;

  display: flex;

  align-items: center;

  justify-content: space-between;

  gap: 30px;
}


/* =========================================================
   6. BRAND
   ========================================================= */

.cfa-brand {
  display: inline-flex;

  align-items: center;

  gap: 12px;

  color: #FFFFFF !important;

  text-decoration: none;

  white-space: nowrap;

  flex-shrink: 0;
}


/* =========================================================
   7. LOGO
   ========================================================= */

.cfa-logo {
  width: 46px;
  height: 46px;

  display: flex;

  align-items: center;
  justify-content: center;

  border-radius: 13px;

  background:
    linear-gradient(
      145deg,
      #60A5FA,
      #2563EB
    );

  color: #FFFFFF;

  font-size: 20px;

  box-shadow:
    0 7px 20px rgba(37, 99, 235, 0.28);

  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease;
}


.cfa-brand:hover .cfa-logo {
  transform:
    translateY(-2px)
    scale(1.04);

  box-shadow:
    0 10px 26px rgba(37, 99, 235, 0.40);
}


/* =========================================================
   8. MEALCARE BRAND NAME
   ========================================================= */

.cfa-brand-name {
  color: #FFFFFF !important;

  font-size: 22px !important;

  font-weight: 800 !important;

  letter-spacing: -0.5px;

  line-height: 1;
}


/* =========================================================
   9. NAVIGATION
   ========================================================= */

.cfa-nav-links {
  position: relative;
  z-index: 2;

  display: flex;

  align-items: center;

  justify-content: center;

  gap: 8px;

  margin-left: auto;
  margin-right: auto;
}


/* =========================================================
   10. NAVIGATION LINKS
   ========================================================= */

.cfa-nav-links a {
  position: relative;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  min-height: 42px;

  padding: 0 17px;

  color: #CBD5E1 !important;

  background: transparent;

  border-radius: 10px;

  font-size: 15px !important;

  font-weight: 600 !important;

  line-height: 1;

  text-decoration: none !important;

  white-space: nowrap;

  transition:
    color 0.25s ease,
    background 0.25s ease,
    transform 0.25s ease;
}


/* =========================================================
   11. NAVIGATION HOVER
   ========================================================= */

.cfa-nav-links a:hover {
  color: #FFFFFF !important;

  background: rgba(96, 165, 250, 0.10);

  transform: translateY(-1px);
}


/* =========================================================
   12. NAVIGATION UNDERLINE
   ========================================================= */

.cfa-nav-links a::after {
  content: "";

  position: absolute;

  left: 50%;
  bottom: 4px;

  width: 0;
  height: 2px;

  border-radius: 10px;

  background: #60A5FA;

  transform: translateX(-50%);

  transition:
    width 0.25s ease;
}


.cfa-nav-links a:hover::after {
  width: 24px;
}


/* =========================================================
   13. NAVIGATION ACTIONS
   ========================================================= */

.cfa-nav-actions {
  position: relative;
  z-index: 2;

  display: flex;

  align-items: center;

  gap: 12px;

  flex-shrink: 0;
}


/* =========================================================
   14. LOGIN BUTTON
   ========================================================= */

.cfa-login-btn {
  position: relative;

  display: inline-flex;

  align-items: center;

  justify-content: center;

  min-width: 104px;

  height: 46px;

  padding: 0 23px;

  overflow: hidden;

  background:
    linear-gradient(
      135deg,
      #2563EB 0%,
      #3B82F6 100%
    );

  color: #FFFFFF !important;

  border:
    1px solid rgba(255, 255, 255, 0.12);

  border-radius: 10px;

  font-size: 15px !important;

  font-weight: 700 !important;

  line-height: 1;

  text-decoration: none !important;

  box-shadow:
    0 8px 22px rgba(37, 99, 235, 0.22);

  transition:
    transform 0.25s ease,
    box-shadow 0.25s ease,
    background 0.25s ease;
}


/* =========================================================
   15. LOGIN SHINE
   ========================================================= */

.cfa-login-btn::before {
  content: "";

  position: absolute;

  top: 0;
  bottom: 0;

  left: -120%;

  width: 70%;

  background:
    linear-gradient(
      90deg,
      transparent,
      rgba(255, 255, 255, 0.30),
      transparent
    );

  transform: skewX(-20deg);

  transition:
    left 0.6s ease;
}


.cfa-login-btn:hover::before {
  left: 140%;
}


/* =========================================================
   16. LOGIN HOVER
   ========================================================= */

.cfa-login-btn:hover {
  color: #FFFFFF !important;

  background:
    linear-gradient(
      135deg,
      #1D4ED8 0%,
      #2563EB 100%
    );

  transform: translateY(-2px);

  box-shadow:
    0 13px 30px rgba(37, 99, 235, 0.34);
}


.cfa-login-btn:active {
  transform:
    translateY(0)
    scale(0.98);
}


/* =========================================================
   17. MOBILE MENU BUTTON
   ========================================================= */

.cfa-menu-toggle {
  display: none;

  width: 44px;
  height: 44px;

  align-items: center;
  justify-content: center;

  padding: 0;

  background:
    rgba(96, 165, 250, 0.08);

  color: #60A5FA;

  border:
    1px solid rgba(96, 165, 250, 0.25);

  border-radius: 10px;

  font-size: 20px;

  cursor: pointer;

  transition:
    background 0.25s ease,
    color 0.25s ease,
    transform 0.25s ease;
}


.cfa-menu-toggle:hover {
  background: #2563EB;

  color: #FFFFFF;

  transform: translateY(-1px);
}


/* =========================================================
   18. TABLET
   ========================================================= */

@media (max-width: 991px) {

  .cfa-navbar-inner {
    min-height: 70px;

    padding: 0 28px !important;
  }

  .cfa-nav-links {
    gap: 2px;
  }

  .cfa-nav-links a {
    padding: 0 11px;

    font-size: 14px !important;
  }

  .cfa-brand-name {
    font-size: 20px !important;
  }

  .cfa-logo {
    width: 42px;
    height: 42px;
  }
}


/* =========================================================
   19. MOBILE
   ========================================================= */

@media (max-width: 767px) {

  .cfa-navbar {
    width: 100vw !important;

    margin-left:
      calc(50% - 50vw) !important;
  }

  .cfa-navbar-inner {
    min-height: 68px;

    padding: 0 20px !important;
  }

  .cfa-nav-links {
    display: none;
  }

  .cfa-nav-links.open {

    position: absolute;

    z-index: 999;

    top: 74px;

    left: 18px;
    right: 18px;

    display: flex;

    flex-direction: column;

    align-items: stretch;

    gap: 4px;

    padding: 10px;

    background: #1E293B;

    border:
      1px solid #334155;

    border-radius: 14px;

    box-shadow:
      0 20px 45px rgba(15, 23, 42, 0.30);
  }

  .cfa-nav-links.open a {

    justify-content: flex-start;

    min-height: 46px;

    padding: 0 16px;

    border-radius: 9px;

    font-size: 15px !important;
  }

  .cfa-menu-toggle {
    display: inline-flex;
  }

  .cfa-login-btn {
    min-width: 88px;

    height: 42px;

    padding: 0 17px;

    font-size: 14px !important;
  }

  .cfa-brand-name {
    font-size: 19px !important;
  }

  .cfa-logo {
    width: 40px;
    height: 40px;

    font-size: 17px;
  }
}


/* =========================================================
   20. SMALL MOBILE
   ========================================================= */

@media (max-width: 480px) {

  .cfa-navbar-inner {
    padding: 0 15px !important;

    gap: 10px;
  }

  .cfa-brand {
    gap: 8px;
  }

  .cfa-brand-name {
    font-size: 18px !important;
  }

  .cfa-logo {
    width: 38px;
    height: 38px;

    border-radius: 10px;
  }

  .cfa-login-btn {
    min-width: 78px;

    height: 40px;

    padding: 0 13px;

    font-size: 13px !important;
  }

  .cfa-menu-toggle {
    width: 40px;
    height: 40px;
  }
}


/* =========================================================
   21. ACCESSIBILITY
   ========================================================= */

.cfa-navbar a:focus-visible,
.cfa-navbar button:focus-visible {

  outline:
    2px solid #60A5FA;

  outline-offset:
    3px;

  border-radius:
    8px;
}


/* =========================================================
   22. REDUCED MOTION
   ========================================================= */

@media (prefers-reduced-motion: reduce) {

  .cfa-navbar *,
  .cfa-navbar *::before,
  .cfa-navbar *::after {

    animation: none !important;

    transition: none !important;
  }
}
